import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import { ShoppingBag, Loader2, Star } from "lucide-react";
import { useCart } from "@/context/CartContext";
import { toast } from "sonner";
import { supabase } from "@/lib/supabaseClient";
import { CloudinaryImage } from "@/components/ui/CloudinaryImage";
import { useState, useEffect } from "react";

interface Product {
  id: string;
  name: string;
  price: number;
  original_price?: number;
  category: string;
  image_url: string;
  stock: string;
  avg_rating?: number;
  review_count?: number;
}

const BestSellers = () => {
  const { addToCart } = useCart();
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchBestSellers();
  }, []);

  const fetchBestSellers = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .neq('stock', 'Out of Stock')
      .order('created_at', { ascending: false })
      .limit(6);

    if (error) {
      console.error('Error fetching products:', error);
    } else {
      setProducts(data || []);
    }
    setLoading(false);
  };

  return (
    <section className="py-16 lg:py-24 bg-secondary">
      <div className="container mx-auto px-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center mb-12"
        >
          <p className="text-primary text-xs tracking-[0.3em] uppercase mb-2 font-body">Most Loved</p>
          <h2 className="font-heading text-3xl lg:text-4xl font-bold text-foreground">Best Sellers</h2>
        </motion.div>

        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : (
          <>
            <div className="grid grid-cols-2 lg:grid-cols-3 gap-3 xs:gap-4 sm:gap-8 lg:gap-10">
              {products.map((product, i) => (
                <motion.div
                  key={product.id}
                  initial={{ opacity: 0, y: 30 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ delay: i * 0.1 }}
                  className="group bg-card rounded-2xl overflow-hidden shadow-soft hover:shadow-elevated transition-all duration-500 flex flex-col h-full"
                >
                  <Link to={`/product/${product.id}`} className="block relative aspect-square overflow-hidden bg-muted/5">
                    <CloudinaryImage
                      src={product.image_url || '/placeholder.svg'}
                      alt={product.name}
                      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                      width={600}
                      height={600}
                    />
                    <div className="absolute top-4 left-4 flex flex-col gap-2">
                      {product.stock === "Low Stock" && (
                        <span className="bg-amber-500 text-white text-[9px] px-2.5 py-1 rounded-full font-bold uppercase tracking-widest shadow-sm">
                          Low Stock
                        </span>
                      )}
                      {product.original_price && product.original_price > product.price && (
                        <span className="bg-primary text-primary-foreground text-[9px] px-2.5 py-1 rounded-full font-bold uppercase tracking-widest shadow-md">
                          {Math.round(((product.original_price - product.price) / product.original_price) * 100)}% OFF
                        </span>
                      )}
                    </div>
                  </Link>
                  <div className="p-3 sm:p-6 flex flex-col flex-grow">
                    <Link to={`/product/${product.id}`}>
                      <h3 className="font-heading text-sm sm:text-lg font-bold text-foreground mb-1 group-hover:text-primary transition-colors line-clamp-1">
                        {product.name}
                      </h3>
                    </Link>
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-baseline gap-2">
                        <span className="text-primary font-bold text-base sm:text-xl">₹{product.price.toLocaleString("en-IN")}</span>
                        {product.original_price && product.original_price > product.price && (
                          <span className="text-xs text-muted-foreground line-through opacity-60">₹{product.original_price.toLocaleString("en-IN")}</span>
                        )}
                      </div>
                      <div className="flex items-center gap-1.5 bg-amber-50 px-2.5 py-1 rounded-lg border border-amber-100/50">
                        <Star className="w-3 h-3 fill-amber-400 text-amber-400" />
                        <span className="text-[11px] font-black text-amber-700">
                          {product.avg_rating ? Number(product.avg_rating).toFixed(1) : "5.0"}
                        </span>
                      </div>
                    </div>
                    <div className="mt-auto">
                      <button
                        onClick={() => {
                          const isAvailable = product.stock !== "Out of Stock";
                          if (!isAvailable) return;

                          addToCart({
                            id: product.id,
                            name: product.name,
                            price: product.price,
                            image: product.image_url,
                            category: product.category as "earrings" | "rings" | "necklaces" | "bangles",
                            inStock: isAvailable,
                            description: "",
                            images: [product.image_url],
                            original_price: product.original_price,
                            stock_quantity: (product as any).stock_quantity
                          });
                          toast.success(`${product.name} added to cart`);
                        }}
                        disabled={product.stock === "Out of Stock"}
                        className="w-full flex items-center justify-center gap-3 py-3 rounded-full border border-border text-foreground text-sm font-bold tracking-wide hover:gradient-gold hover:text-primary-foreground hover:border-transparent transition-all duration-300 disabled:opacity-40 disabled:cursor-not-allowed uppercase"
                      >
                        {product.stock === "Out of Stock" ? "Sold Out" : "Add to Cart"}
                      </button>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            <div className="text-center mt-10">
              <Link
                to="/shop"
                className="inline-flex items-center px-8 py-3 rounded-full border border-primary text-primary font-medium text-sm tracking-wide hover:gradient-gold hover:text-primary-foreground hover:border-transparent transition-all duration-300"
              >
                View All Products
              </Link>
            </div>
          </>
        )}
      </div>
    </section>
  );
};

export default BestSellers;

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabaseClient";

interface AnnouncementSettings {
    enabled: boolean;
    text: string;
    bgColor: string;
    textColor: string;
}

const AnnouncementBar = () => {
    const [settings, setSettings] = useState<AnnouncementSettings | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchSettings = async () => {
            const { data } = await supabase.from('app_settings').select('*').in('key', ['announcement_enabled', 'announcement_text', 'announcement_bg_color', 'announcement_text_color']);

            if (data) {
                const config: any = {};
                data.forEach(item => {
                    config[item.key] = item.value;
                });
                setSettings({
                    enabled: config.announcement_enabled,
                    text: config.announcement_text,
                    bgColor: config.announcement_bg_color || '#000000',
                    textColor: config.announcement_text_color || '#ffffff'
                });
            }
            setLoading(false);
        };

        fetchSettings();

        // Realtime subscription using channel
        const channel = supabase
            .channel('announcement_settings')
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'app_settings'
                },
                (payload) => {
                    // Refresh if any announcement setting changes
                    if (payload.new.key.startsWith('announcement_')) {
                        fetchSettings();
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, []);

    if (loading || !settings || !settings.enabled) return null;

    return (
        <div
            className="w-full py-2.5 overflow-hidden relative z-50 flex items-center justify-center font-medium text-sm tracking-wide"
            style={{ backgroundColor: settings.bgColor, color: settings.textColor }}
        >
            <div className="flex animate-marquee whitespace-nowrap items-center">
                {/* Repeat the text 8 times to fill the screen and loop smoothly */}
                {[...Array(8)].map((_, i) => (
                    <span
                        key={i}
                        onClick={() => {
                            navigator.clipboard.writeText(settings.text);
                            // Using a simple alert or toast if available. Since toast is imported in other files but not here, let's just use cursor pointer for now or add toast.
                            // Ideally use the sonner toast if available.
                            import("sonner").then(({ toast }) => toast.success("Announcement copied to clipboard!"));
                        }}
                        className="mx-8 font-semibold uppercase tracking-widest text-sm cursor-pointer hover:underline"
                        title="Click to copy"
                    >
                        {settings.text}
                    </span>
                ))}
            </div>

            <style>
                {`
                @keyframes marquee {
                    0% { transform: translateX(0); }
                    100% { transform: translateX(-50%); }
                }
                .animate-marquee {
                    animation: marquee 40s linear infinite;
                    display: flex;
                    min-width: 200%;
                }
                .animate-marquee:hover {
                    animation-play-state: paused;
                }
                `}
            </style>
        </div>
    );
};

export default AnnouncementBar;

import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/lib/supabaseClient";
import { CloudinaryImage } from "@/components/ui/CloudinaryImage";
import { Loader2, Star } from "lucide-react";

interface Product {
    id: string;
    name: string;
    price: number;
    image_url: string;
    category: string;
    stock: string;
    original_price?: number;
    avg_rating?: number;
    review_count?: number;
}

interface RelatedProductsProps {
    currentProductId: string;
    category: string;
}

const RelatedProducts = ({ currentProductId, category }: RelatedProductsProps) => {
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchRelated = async () => {
            setLoading(true);
            try {
                // 1. Try to fetch by category first
                let { data, error } = await supabase
                    .from('products')
                    .select('id, name, price, original_price, image_url, category, stock, avg_rating, review_count')
                    .eq('category', category)
                    .neq('id', currentProductId)
                    .limit(4);

                if (error) throw error;

                // 2. If no products found in category, fetch random ones
                if (!data || data.length === 0) {
                    const { data: fallbackData, error: fallbackError } = await supabase
                        .from('products')
                        .select('id, name, price, original_price, image_url, category, stock, avg_rating, review_count')
                        .neq('id', currentProductId)
                        .limit(4);

                    if (fallbackError) throw fallbackError;
                    setProducts(fallbackData || []);
                } else {
                    setProducts(data);
                }
            } catch (err) {
                console.error("Error fetching related products:", err);
            } finally {
                setLoading(false);
            }
        };

        if (category !== undefined) {
            fetchRelated();
        }
    }, [category, currentProductId]);

    if (loading) return <div className="py-10 flex justify-center"><Loader2 className="animate-spin h-6 w-6 text-primary" /></div>;
    if (products.length === 0) return null;

    return (
        <div className="py-12 border-t mt-12">
            <h3 className="text-2xl font-bold font-heading mb-6">Related Products</h3>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-6">
                {products.map((product) => (
                    <Link key={product.id} to={`/product/${product.id}`} className="group block bg-card rounded-xl overflow-hidden shadow-sm hover:shadow-md transition-all">
                        <div className="aspect-square relative overflow-hidden">
                            <CloudinaryImage
                                src={product.image_url || '/placeholder.svg'}
                                alt={product.name}
                                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                            />
                            <div className="absolute top-2 left-2 flex flex-col gap-1.5">
                                {product.stock !== "In Stock" && (
                                    <span className="bg-black/60 text-white text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-wider backdrop-blur-sm shadow-sm">
                                        {product.stock === "Low Stock" ? "Low Stock" : "Sold Out"}
                                    </span>
                                )}
                                {product.original_price && product.original_price > product.price && (
                                    <span className="bg-primary text-primary-foreground text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-wider shadow-md">
                                        {Math.round(((product.original_price - product.price) / product.original_price) * 100)}% OFF
                                    </span>
                                )}
                            </div>
                        </div>
                        <div className="p-4">
                            <p className="text-xs text-muted-foreground mb-1 uppercase tracking-wider">{product.category}</p>
                            <h4 className="font-semibold text-foreground line-clamp-1 group-hover:text-primary transition-colors text-sm">
                                {product.name}
                            </h4>
                            <div className="flex items-center justify-between mt-1">
                                <div className="flex flex-col">
                                    <p className="text-primary font-bold text-sm">₹{product.price.toLocaleString("en-IN")}</p>
                                    {product.original_price && product.original_price > product.price && (
                                        <p className="text-[10px] text-muted-foreground line-through opacity-70">₹{product.original_price.toLocaleString("en-IN")}</p>
                                    )}
                                </div>
                                <div className="flex items-center gap-1 bg-amber-50 px-1.5 py-0.5 rounded-md self-end">
                                    <Star className="w-2.5 h-2.5 fill-amber-400 text-amber-400" />
                                    <span className="text-[10px] font-bold text-amber-700">
                                        {product.avg_rating ? Number(product.avg_rating).toFixed(1) : "5.0"}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </Link>
                ))}
            </div>
        </div>
    );
};

export default RelatedProducts;

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
        secondary: "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive: "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 rounded-md px-3",
        lg: "h-11 rounded-md px-8",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />;
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };

import * as React from "react";
import { type DialogProps } from "@radix-ui/react-dialog";
import { Command as CommandPrimitive } from "cmdk";
import { Search } from "lucide-react";

import { cn } from "@/lib/utils";
import { Dialog, DialogContent } from "@/components/ui/dialog";

const Command = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive>
>(({ className, ...props }, ref) => (
  <CommandPrimitive
    ref={ref}
    className={cn(
      "flex h-full w-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground",
      className,
    )}
    {...props}
  />
));
Command.displayName = CommandPrimitive.displayName;

interface CommandDialogProps extends DialogProps {}

const CommandDialog = ({ children, ...props }: CommandDialogProps) => {
  return (
    <Dialog {...props}>
      <DialogContent className="overflow-hidden p-0 shadow-lg">
        <Command className="[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground [&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-0 [&_[cmdk-group]]:px-2 [&_[cmdk-input-wrapper]_svg]:h-5 [&_[cmdk-input-wrapper]_svg]:w-5 [&_[cmdk-input]]:h-12 [&_[cmdk-item]]:px-2 [&_[cmdk-item]]:py-3 [&_[cmdk-item]_svg]:h-5 [&_[cmdk-item]_svg]:w-5">
          {children}
        </Command>
      </DialogContent>
    </Dialog>
  );
};

const CommandInput = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Input>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Input>
>(({ className, ...props }, ref) => (
  <div className="flex items-center border-b px-3" cmdk-input-wrapper="">
    <Search className="mr-2 h-4 w-4 shrink-0 opacity-50" />
    <CommandPrimitive.Input
      ref={ref}
      className={cn(
        "flex h-11 w-full rounded-md bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
      {...props}
    />
  </div>
));

CommandInput.displayName = CommandPrimitive.Input.displayName;

const CommandList = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.List>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.List>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.List
    ref={ref}
    className={cn("max-h-[300px] overflow-y-auto overflow-x-hidden", className)}
    {...props}
  />
));

CommandList.displayName = CommandPrimitive.List.displayName;

const CommandEmpty = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Empty>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Empty>
>((props, ref) => <CommandPrimitive.Empty ref={ref} className="py-6 text-center text-sm" {...props} />);

CommandEmpty.displayName = CommandPrimitive.Empty.displayName;

const CommandGroup = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Group>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Group>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Group
    ref={ref}
    className={cn(
      "overflow-hidden p-1 text-foreground [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground",
      className,
    )}
    {...props}
  />
));

CommandGroup.displayName = CommandPrimitive.Group.displayName;

const CommandSeparator = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Separator ref={ref} className={cn("-mx-1 h-px bg-border", className)} {...props} />
));
CommandSeparator.displayName = CommandPrimitive.Separator.displayName;

const CommandItem = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Item>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Item
    ref={ref}
    className={cn(
      "relative flex cursor-default select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none data-[disabled=true]:pointer-events-none data-[selected='true']:bg-accent data-[selected=true]:text-accent-foreground data-[disabled=true]:opacity-50",
      className,
    )}
    {...props}
  />
));

CommandItem.displayName = CommandPrimitive.Item.displayName;

const CommandShortcut = ({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) => {
  return <span className={cn("ml-auto text-xs tracking-widest text-muted-foreground", className)} {...props} />;
};
CommandShortcut.displayName = "CommandShortcut";

export {
  Command,
  CommandDialog,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandShortcut,
  CommandSeparator,
};

import * as React from "react";
import * as LabelPrimitive from "@radix-ui/react-label";
import { Slot } from "@radix-ui/react-slot";
import { Controller, ControllerProps, FieldPath, FieldValues, FormProvider, useFormContext } from "react-hook-form";

import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";

const Form = FormProvider;

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName;
};

const FormFieldContext = React.createContext<FormFieldContextValue>({} as FormFieldContextValue);

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  );
};

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext);
  const itemContext = React.useContext(FormItemContext);
  const { getFieldState, formState } = useFormContext();

  const fieldState = getFieldState(fieldContext.name, formState);

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>");
  }

  const { id } = itemContext;

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  };
};

type FormItemContextValue = {
  id: string;
};

const FormItemContext = React.createContext<FormItemContextValue>({} as FormItemContextValue);

const FormItem = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const id = React.useId();

    return (
      <FormItemContext.Provider value={{ id }}>
        <div ref={ref} className={cn("space-y-2", className)} {...props} />
      </FormItemContext.Provider>
    );
  },
);
FormItem.displayName = "FormItem";

const FormLabel = React.forwardRef<
  React.ElementRef<typeof LabelPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root>
>(({ className, ...props }, ref) => {
  const { error, formItemId } = useFormField();

  return <Label ref={ref} className={cn(error && "text-destructive", className)} htmlFor={formItemId} {...props} />;
});
FormLabel.displayName = "FormLabel";

const FormControl = React.forwardRef<React.ElementRef<typeof Slot>, React.ComponentPropsWithoutRef<typeof Slot>>(
  ({ ...props }, ref) => {
    const { error, formItemId, formDescriptionId, formMessageId } = useFormField();

    return (
      <Slot
        ref={ref}
        id={formItemId}
