import { createContext, useContext, useEffect, useState, ReactNode, useCallback } from 'react';
import { User, Session, AuthResponse } from '@supabase/supabase-js';
import { supabaseAdmin } from '@/lib/supabaseAdminClient';

interface AdminAuthContextType {
    user: User | null;
    session: Session | null;
    userRole: string | null;
    loading: boolean;
    signIn: (email: string, password: string) => Promise<AuthResponse>;
    signOut: () => Promise<void>;
    isAdmin: () => boolean;
}

const AdminAuthContext = createContext<AdminAuthContextType | undefined>(undefined);

export const AdminAuthProvider = ({ children }: { children: ReactNode }) => {
    const [user, setUser] = useState<User | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [userRole, setUserRole] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    const fetchUserRole = useCallback(async (userId: string) => {
        console.log('🔐 AdminAuthContext - Fetching role for:', userId);
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000); // 5s timeout

        try {
            const { data, error } = await supabaseAdmin
                .from('user_roles')
                .select('role')
                .eq('user_id', userId)
                .maybeSingle();

            clearTimeout(timeoutId);

            if (error) {
                console.error('🔐 AdminAuthContext - Error fetching role:', error);
                setUserRole(null);
            } else {
                console.log('🔐 AdminAuthContext - Role fetched:', data?.role);
                setUserRole(data?.role || null);
            }
        } catch (err) {
            clearTimeout(timeoutId);
            console.error('🔐 AdminAuthContext - Critical role fetch error:', err);
            setUserRole(null);
        }
    }, []);

    useEffect(() => {
        let mounted = true;

        const initSession = async () => {
            try {
                const { data: { session: currentSession } } = await supabaseAdmin.auth.getSession();
                if (!mounted) return;

                if (currentSession?.user) {
                    setSession(currentSession);
                    setUser(currentSession.user);
                    // Non-blocking role fetch to speed up initial load
                    fetchUserRole(currentSession.user.id).finally(() => {
                        if (mounted) setLoading(false);
                    });
                } else {
                    setSession(null);
                    setUser(null);
                    setUserRole(null);
                    setLoading(false);
                }
            } catch (error) {
                console.error('🔐 AdminAuthContext - Initialization error:', error);
                setLoading(false);
            }
        };

        const { data: { subscription } } = supabaseAdmin.auth.onAuthStateChange(async (event, currentSession) => {
            console.log('🔐 AdminAuthContext - Auth state changed:', event);

            if (!mounted) return;

            if (currentSession?.user) {
                setSession(currentSession);
                setUser(currentSession.user);
                // Don't await here to prevent blocking state updates
                fetchUserRole(currentSession.user.id).finally(() => {
                    if (mounted) setLoading(false);
                });
            } else {
                setSession(null);
                setUser(null);
                setUserRole(null);
                setLoading(false);
            }
        });

        initSession();

        return () => {
            mounted = false;
            subscription.unsubscribe();
        };
    }, [fetchUserRole]);

    const signIn = async (email: string, password: string) => {
        return await supabaseAdmin.auth.signInWithPassword({ email, password });
    };

    const signOut = async () => {
        try {
            await supabaseAdmin.auth.signOut();
            setUser(null);
            setSession(null);
            setUserRole(null);
        } catch (error) {
            console.error('🔐 AdminAuthContext - Signout error:', error);
        }
    };

    const isAdmin = () => userRole === 'admin';

    return (
        <AdminAuthContext.Provider value={{ user, session, userRole, loading, signIn, signOut, isAdmin }}>
            {children}
        </AdminAuthContext.Provider>
    );
};

export const useAdminAuth = () => {
    const context = useContext(AdminAuthContext);
    if (context === undefined) {
        throw new Error('useAdminAuth must be used within an AdminAuthProvider');
    }
    return context;
};

import { createContext, useContext, useEffect, useState, ReactNode, useMemo } from 'react';
import { supabaseAdmin } from '@/lib/supabaseAdminClient';
import { useAdminAuth } from './AdminAuthContext';
import { toast } from 'sonner';

interface Notification {
    id: string;
    title: string;
    message: string;
    type: string;
    is_read: boolean;
    link?: string;
    metadata?: Record<string, unknown>;
    created_at: string;
}

interface AdminNotificationContextType {
    notifications: Notification[];
    unreadCount: number;
    loading: boolean;
    markAsRead: (id: string) => Promise<void>;
    markAllAsRead: () => Promise<void>;
    clearAll: () => Promise<void>;
}

const AdminNotificationContext = createContext<AdminNotificationContextType | undefined>(undefined);

export const AdminNotificationProvider = ({ children }: { children: ReactNode }) => {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [loading, setLoading] = useState(true);
    const { user, userRole } = useAdminAuth();



    const playNotificationSound = () => {
        try {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            const audioCtx = new AudioContextClass();

            // Create a professional "chime" sound
            const oscillator = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();

            oscillator.type = 'sine';
            oscillator.frequency.setValueAtTime(880, audioCtx.currentTime); // A5
            oscillator.frequency.exponentialRampToValueAtTime(440, audioCtx.currentTime + 0.5); // A4

            gainNode.gain.setValueAtTime(0, audioCtx.currentTime);
            gainNode.gain.linearRampToValueAtTime(0.2, audioCtx.currentTime + 0.1);
            gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.8);

            oscillator.connect(gainNode);
            gainNode.connect(audioCtx.destination);

            oscillator.start();
            oscillator.stop(audioCtx.currentTime + 0.8);
        } catch (err) {
            console.error('Could not play notification sound:', err);
        }
    };

    useEffect(() => {
        const fetchNotifications = async () => {
            if (!user || userRole !== 'admin') return;

            try {
                const { data, error } = await supabaseAdmin
                    .from('notifications')
                    .select('*')
                    .order('created_at', { ascending: false })
                    .limit(20);

                if (error) throw error;
                setNotifications(data || []);
            } catch (err) {
                console.error('Error fetching notifications:', err);
            } finally {
                setLoading(false);
            }
        };

        if (user && userRole === 'admin') {
            fetchNotifications();

            // Real-time subscription
            const channel = supabaseAdmin
                .channel('admin-notifications-sync')
                .on(
                    'postgres_changes',
                    {
                        event: 'INSERT',
                        schema: 'public',
                        table: 'notifications'
                    },
                    (payload) => {
                        const newNotification = payload.new as Notification;
                        setNotifications((prev) => [newNotification, ...prev].slice(0, 20));

                        // Show toast and play sound for new orders
                        if (newNotification.type === 'order') {
                            // Play the chime sound
                            playNotificationSound();

                            toast.success(newNotification.title, {
                                description: newNotification.message,
                                duration: 10000,
                            });
                        }
                    }
                )
                .subscribe();

            return () => {
                if (channel) {
                    // Only attempt to remove if not already closed/errored to prevent 
                    // "WebSocket is closed before the connection is established" errors
                    if (channel.state === 'closed' || channel.state === 'errored') {
                        return;
                    }

                    supabaseAdmin.removeChannel(channel).catch(() => {
                        // Silent cleanup failure
                    });
                }
            };
        }
    }, [user, userRole]);

    const markAsRead = async (id: string) => {
        try {
            const { error } = await supabaseAdmin
                .from('notifications')
                .update({ is_read: true })
                .eq('id', id);

            if (error) throw error;
            setNotifications((prev) =>
                prev.map((n) => (n.id === id ? { ...n, is_read: true } : n))
            );
        } catch (err) {
            console.error('Error marking notification as read:', err);
        }
    };

    const markAllAsRead = async () => {
        try {
            const { error } = await supabaseAdmin
                .from('notifications')
                .update({ is_read: true })
                .eq('is_read', false);

            if (error) throw error;
            setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
        } catch (err) {
            console.error('Error marking all as read:', err);
        }
    };

    const clearAll = async () => {
        try {
            const { error } = await supabaseAdmin
                .from('notifications')
                .delete()
                .neq('id', '00000000-0000-0000-0000-000000000000'); // Delete all

            if (error) throw error;
            setNotifications([]);
        } catch (err) {
            console.error('Error clearing notifications:', err);
        }
    };

    const unreadCount = notifications.filter((n) => !n.is_read).length;

    const value = useMemo(() => ({
        notifications, unreadCount, loading, markAsRead, markAllAsRead, clearAll
    }), [notifications, unreadCount, loading]);

    return (
        <AdminNotificationContext.Provider value={value}>
            {children}
        </AdminNotificationContext.Provider>
    );
};

export const useAdminNotifications = () => {
    const context = useContext(AdminNotificationContext);
    if (context === undefined) {
        throw new Error('useAdminNotifications must be used within an AdminNotificationProvider');
    }
    return context;
};

import { createContext, useContext, useEffect, useState, ReactNode, useCallback, useMemo } from 'react';
import { User, Session, AuthError, PostgrestError } from '@supabase/supabase-js';
import { supabase } from '@/lib/supabaseClient';

interface Profile {
    id: string;
    username: string | null;
    phone_number: string | null;
    full_name: string | null;
    avatar_url: string | null;
}

interface AuthContextType {
    user: User | null;
    profile: Profile | null;
    session: Session | null;
    userRole: string | null;
    loading: boolean;
    signIn: (email: string, password: string) => Promise<{ error: AuthError | null }>;
    signInWithOTP: (email: string) => Promise<{ error: AuthError | null }>;
    signInWithIdentifier: (identifier: string, password: string) => Promise<{ error: AuthError | null | { message: string } }>;
    verifyOTP: (email: string, token: string) => Promise<{ error: AuthError | null }>;
    signUp: (data: { email?: string; password: string; fullName?: string; username?: string; phone?: string }) => Promise<{ error: AuthError | null }>;
    signOut: () => Promise<void>;
    isAdmin: () => boolean;
    displayIdentifier: string | null;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
    const [user, setUser] = useState<User | null>(null);
    const [profile, setProfile] = useState<Profile | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [userRole, setUserRole] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    const fetchProfile = useCallback(async (userId: string) => {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', userId)
            .maybeSingle();

        if (error) {
            console.error('Error fetching profile:', error);
        } else if (data) {
            setProfile(data);
        }
    }, []);

    const fetchUserRole = useCallback(async (userId: string) => {
        const { data, error } = await supabase
            .from('user_roles')
            .select('role')
            .eq('user_id', userId)
            .maybeSingle();

        if (error) {
            console.error('Error fetching user role:', error);
            setUserRole('customer');
        } else if (!data) {
            console.log('No role found for user, creating customer role...');
            await supabase
                .from('user_roles')
                .insert({ user_id: userId, role: 'customer' });
            setUserRole('customer');
        } else {
            setUserRole(data.role || 'customer');
        }
    }, []);

    useEffect(() => {
        let mounted = true;

        // Initialize session
        const initSession = async () => {
            try {
                const { data: { session } } = await supabase.auth.getSession();
                if (!mounted) return;

                if (session?.user) {
                    setSession(session);
                    setUser(session.user);
                    // Fetch profile and role
                    await Promise.all([
                        fetchProfile(session.user.id),
                        fetchUserRole(session.user.id)
                    ]);
                    if (mounted) setLoading(false);
                } else {
                    setSession(null);
                    setUser(null);
                    setProfile(null);
                    setLoading(false);
                }
            } catch (error) {
                console.error('Auth initialization error:', error);
                setLoading(false);
            }
        };

        initSession();

        const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
            if (_event === 'SIGNED_IN') {
                setSession(session);
                setUser(session?.user ?? null);
                if (session?.user) {
                    Promise.all([
                        fetchProfile(session.user.id),
                        fetchUserRole(session.user.id)
                    ]).finally(() => {
                        setLoading(false);
                    });
                } else {
                    setLoading(false);
                }
            } else if (_event === 'SIGNED_OUT') {
                setSession(null);
                setUser(null);
                setProfile(null);
                setUserRole(null);
                setLoading(false);
            }
        });

        return () => {
            mounted = false;
            subscription.unsubscribe();
        };
    }, [fetchProfile, fetchUserRole]);

    const signIn = async (email: string, password: string) => {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        return { error };
    };

    const signInWithIdentifier = async (identifier: string, password: string) => {
        const trimmedIdentifier = identifier.trim();
        console.log('🔑 Attempting login for:', trimmedIdentifier);

        // 1. Try Email direct sign in
        if (trimmedIdentifier.includes('@')) {
            console.log('ℹ️ Detected email format, signing in directly.');
            return await signIn(trimmedIdentifier, password);
        }

        // 2. Try Phone or Username lookup
        // We use quotes "val" for values in .or() to handle special characters
        console.log(`🔍 Searching profiles for identifier: "${trimmedIdentifier}"`);
        const { data: profileData, error: lookupError } = await supabase
            .from('profiles')
            .select('email, username, phone_number')
            .or(`username.eq."${trimmedIdentifier}",phone_number.eq."${trimmedIdentifier}"`)
            .maybeSingle();

        if (lookupError) {
            console.error('❌ Profile lookup query error:', lookupError);
        }

        if (profileData?.email) {
            console.log('✅ Found account email:', profileData.email);
            return await signIn(profileData.email, password);
        }

        console.warn('⚠️ No account found with that username or phone number.');
        // Fallback or Error
        return { error: { message: "Invalid username, phone, or password. Please try again." } };
    };

    const signInWithOTP = async (email: string) => {
        const { error } = await supabase.auth.signInWithOtp({
            email,
            options: { shouldCreateUser: true }
        });
        return { error };
    };

    const verifyOTP = async (email: string, token: string) => {
        const { error } = await supabase.auth.verifyOtp({
            email,
            token,
            type: 'email'
        });
        return { error };
    };

    const signUp = async (data: { email?: string; password: string; fullName?: string; username?: string; phone?: string }) => {
        // Generate a placeholder email if none provided
        const userEmail = data.email || `${data.username || Date.now()}@kvp.internal`;

        const { data: authData, error } = await supabase.auth.signUp({
            email: userEmail,
            password: data.password,
            options: {
                data: {
                    full_name: data.fullName,
                    username: data.username,
                    phone: data.phone
                }
            }
        });

        if (!error && authData.user) {
            // Role assignment
            await supabase.from('user_roles').upsert({
                user_id: authData.user.id,
                role: 'customer'
            }, { onConflict: 'user_id' });

            // Profile update (Ensure everything is synced)
            await supabase.from('profiles').upsert({
                id: authData.user.id,
                username: data.username,
                phone_number: data.phone,
                email: userEmail,
                full_name: data.fullName
            }, { onConflict: 'id' });

            // Force fetch profile to update context immediately
            await fetchProfile(authData.user.id);
        }
        return { error };
    };

    const signOut = async () => {
        await supabase.auth.signOut();
        setProfile(null);
        setUserRole(null);
    };

    const isAdmin = () => userRole === 'admin';

    const displayIdentifier = user?.email?.endsWith('@kvp.internal')
        ? (profile?.username || profile?.phone_number || "User")
        : (user?.email || null);

    const value = useMemo(() => ({
        user, profile, session, userRole, loading,
        signIn, signInWithOTP, signInWithIdentifier,
        verifyOTP, signUp, signOut, isAdmin,
        displayIdentifier
    }), [user, profile, session, userRole, loading, fetchProfile, fetchUserRole]);

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { createContext, useContext, useState, useCallback, useMemo } from "react";
import { Product } from "@/data/products";
import { supabase } from "@/lib/supabaseClient";
import { useAuth } from "@/context/AuthContext";
import { toast } from "sonner";

export type CartItem = {
  product: Product;
  quantity: number;
};

type CartContextType = {
  items: CartItem[];
  addToCart: (product: Product) => void;
  removeFromCart: (productId: string) => void;
  updateQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  totalItems: number;
  totalAmount: number;
};

const CartContext = createContext<CartContextType | undefined>(undefined);

export const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [items, setItems] = useState<CartItem[]>(() => {
    // Initial load from local storage for everyone
    const savedCart = localStorage.getItem("cartLines");
    return savedCart ? JSON.parse(savedCart) : [];
  });

  // Sync with Supabase when user changes
  React.useEffect(() => {
    if (user) {
      fetchCart();
    }
  }, [user]);

  // Persist to local storage (for guests or offline backup)
  React.useEffect(() => {
    localStorage.setItem("cartLines", JSON.stringify(items));
  }, [items]);

  const fetchCart = async () => {
    if (!user?.id) return;
    try {
      const { data, error } = await supabase
        .from('cart_items')
        .select('*, product:products(*)')
        .eq('user_id', user.id);

      if (error) {
        if (error.message?.includes('AbortError')) return;
        throw error;
      }

      if (data) {
        const serverItems: CartItem[] = data
          .filter(item => item.product)
          .map((item) => ({
            product: {
              ...item.product,
              id: item.product.id,
              name: item.product.name,
              price: item.product.price,
              image: item.product.image_url, // Map DB image_url to frontend image field
              image_url: item.product.image_url,
              stock_quantity: item.product.stock_quantity,
              category: item.product.category,
              stock: item.product.stock || (item.product.stock_quantity > 0 ? 'In Stock' : 'Out of Stock')
            },
            quantity: item.quantity
          }));

        // MERGE STRATEGY: Combine local (guest) cart with server cart
        const guestItems = [...items];
        const mergedItems = [...serverItems];

        let hasNewGuestItems = false;

        for (const guestItem of guestItems) {
          const indexInServer = mergedItems.findIndex(si => si.product.id === guestItem.product.id);

          if (indexInServer > -1) {
            // Priority to server or existing logic
          } else {
            // Item only in guest cart -> Add to merged and flag for sync
            mergedItems.push(guestItem);
            hasNewGuestItems = true;
          }
        }

        if (hasNewGuestItems) {
          const batchInsert = mergedItems.map(item => ({
            user_id: user.id,
            product_id: item.product.id,
            quantity: item.quantity,
            updated_at: new Date().toISOString()
          }));

          await supabase.from('cart_items').upsert(batchInsert, { onConflict: 'user_id, product_id' });
        }

        setItems(mergedItems);
      }
    } catch (error) {
      // Cast error safely if needed or check type
      const err = error as Error;
      if (err?.message?.includes('AbortError')) return;
      console.error('Error fetching/merging cart:', error);
    }
  };

  const addToCart = useCallback(async (product: Product) => {
    const existing = items.find((item) => item.product.id === product.id);
    const currentQty = existing ? existing.quantity : 0;
    const maxStock = product.stock_quantity;

    // Only enforce stock limit if stock_quantity is explicitly provided
    if (maxStock !== undefined && currentQty + 1 > maxStock) {
      toast.error(`Only ${maxStock} items available in stock`);
      return;
    }

    setItems((prev) => {
      let newItems;
      if (existing) {
        newItems = prev.map((item) =>
          item.product.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      } else {
        newItems = [...prev, { product, quantity: 1 }];
      }
      return newItems;
    });

    // Supabase Sync - Optimized with upsert
    if (user) {
      try {
        await supabase
          .from('cart_items')
          .upsert({
            user_id: user.id,
            product_id: product.id,
            quantity: currentQty + 1,
            updated_at: new Date().toISOString()
          }, { onConflict: 'user_id, product_id' });
      } catch (error) {
        console.error("Error syncing add to cart:", error);
      }
    }
  }, [items, user]);

  const removeFromCart = useCallback(async (productId: string) => {
    setItems((prev) => prev.filter((item) => item.product.id !== productId));

    if (user) {
      try {
        await supabase
          .from('cart_items')
          .delete()
          .eq('user_id', user.id)
          .eq('product_id', productId);
      } catch (error) {
        console.error("Error syncing remove from cart:", error);
      }
    }
  }, [user]);

  const updateQuantity = useCallback(async (productId: string, quantity: number) => {
    setItems((prev) => {
      const item = prev.find((i) => i.product.id === productId);
      if (!item) return prev;

      const maxStock = item.product.stock_quantity ?? 0;

      if (quantity > maxStock) {
        toast.error(`Only ${maxStock} items available in stock`);
        return prev;
      }

      if (quantity <= 0) {
        return prev.filter((i) => i.product.id !== productId);
      }

      return prev.map((i) => (i.product.id === productId ? { ...i, quantity } : i));
    });

    if (user) {
      try {
        if (quantity <= 0) {
          await supabase
            .from('cart_items')
            .delete()
            .eq('user_id', user.id)
            .eq('product_id', productId);
        } else {
          await supabase
            .from('cart_items')
            .upsert({
              user_id: user.id,
              product_id: productId,
              quantity: quantity,
              updated_at: new Date().toISOString()
            }, { onConflict: 'user_id, product_id' });
        }
      } catch (error) {
        console.error("Error syncing update quantity:", error);
      }
    }
  }, [user]);

  const clearCart = useCallback(async () => {
    setItems([]);
    if (user) {
      try {
        await supabase
          .from('cart_items')
          .delete()
          .eq('user_id', user.id);
      } catch (error) {
        console.error("Error clearing cart:", error);
      }
    }
  }, [user]);

  const totalItems = items.reduce((sum, item) => sum + item.quantity, 0);
  const totalAmount = items.reduce((sum, item) => sum + item.product.price * item.quantity, 0);

  const value = useMemo(() => ({
    items, addToCart, removeFromCart, updateQuantity, clearCart, totalItems, totalAmount
  }), [items, addToCart, removeFromCart, updateQuantity, clearCart, totalItems, totalAmount]);

  return (
    <CartContext.Provider value={value}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) throw new Error("useCart must be used within a CartProvider");
  return context;
};

import { useState } from "react";

import { motion } from "framer-motion";
import { MessageCircle, ArrowLeft, Loader2, CheckCircle2, CreditCard } from "lucide-react";
import { Link, useNavigate } from "react-router-dom";
import { useCart } from "@/context/CartContext";
import { generateWhatsAppOrderUrl } from "@/lib/whatsapp";
import { generateOrderUPILink } from "@/lib/upi";
import { toast } from "sonner";
import { supabase } from "@/lib/supabaseClient";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

const allowedPincodes = [
  "628501", "628502", "628503", "628714", "628720",
  "628712", "628902", "628904", "628721", "628901", "628613"
];

const Checkout = () => {
  const { items, totalAmount, clearCart } = useCart();
  const navigate = useNavigate();
  const [form, setForm] = useState({ name: "", phone: "", address: "", pincode: "" });
  const [paymentMethod, setPaymentMethod] = useState<"upi" | "cod">("upi");
  const [loading, setLoading] = useState(false);
  const [showPaymentDialog, setShowPaymentDialog] = useState(false);
  const [currentOrderData, setCurrentOrderData] = useState<any>(null);
  const [paymentLink, setPaymentLink] = useState("");

  const shippingFee = totalAmount > 500 ? 0 : 50;
  const grandTotal = totalAmount + shippingFee;

  const isCodAvailable = allowedPincodes.includes(form.pincode);

  // Effect to automatically switch to UPI if COD becomes unavailable
  if (paymentMethod === "cod" && !isCodAvailable && form.pincode.length >= 6) {
    setPaymentMethod("upi");
  }

  if (items.length === 0) {
    return (
      <main className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <h1 className="font-heading text-2xl font-bold text-foreground mb-2">Nothing to checkout</h1>
          <Link to="/shop" className="text-primary text-sm underline">Go to Shop</Link>
        </div>
      </main>
    );
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.name || !form.phone || !form.address || !form.pincode) {
      toast.error("Please fill all fields");
      return;
    }

    if (paymentMethod === "cod" && !isCodAvailable) {
      toast.error("Cash on Delivery is not available for this pincode.");
      return;
    }

    setLoading(true);

    try {
      // 1. Check if user is logged in
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        toast.error("Please login to place an order");
        navigate("/login");
        return;
      }

      // 2. Generate Order Number using secure RPC function
      const { data: orderNumber, error: numError } = await supabase.rpc('get_next_order_number');

      if (numError) throw numError;
      if (!orderNumber) throw new Error("Failed to generate order number");

      // 2. Create Order in Supabase with appropriate status
      const orderStatus = paymentMethod === "upi" ? "pending_payment" : "pending";

      const { data: orderData, error: orderError } = await supabase
        .from('orders')
        .insert({
          user_id: user.id,
          order_number: orderNumber,
          status: orderStatus,
          total_amount: grandTotal,
          shipping_fee: shippingFee,
          shipping_address: form,
          payment_method: paymentMethod
        })
        .select()
        .single();

      if (orderError) throw orderError;

      // 3. Insert Order Items
      const orderItems = items.map(item => ({
        order_id: orderData.id,
        product_id: item.product.id,
        product_name: item.product.name,
        product_image: item.product.image || item.product.image_url,
        quantity: item.quantity,
        price: item.product.price
      }));

      const { error: itemsError } = await supabase
        .from('order_items')
        .insert(orderItems);

      if (itemsError) throw itemsError;

      // 4. Handle payment method
      if (paymentMethod === "upi") {
        // UPI Flow: Open UPI app, then show confirmation dialog
        const upiLink = generateOrderUPILink(orderNumber, grandTotal);
        setPaymentLink(upiLink);

        // Store order data for later use
        setCurrentOrderData({
          orderNumber,
          orderId: orderData.id,
        });

        // Open UPI payment app
        window.location.href = upiLink;

        // Show payment confirmation dialog after a short delay
        setTimeout(() => {
          setShowPaymentDialog(true);
          setLoading(false);
        }, 1000);

      } else {
        // COD Flow: Direct to WhatsApp
        const url = generateWhatsAppOrderUrl({
          products: items.map((item) => ({
            name: item.product.name,
            price: item.product.price * item.quantity,
            quantity: item.quantity,
          })),
          total: grandTotal,
          shippingFee: shippingFee,
          customerName: form.name,
          customerPhone: form.phone,
          customerAddress: `${form.address}, ${form.pincode}`,
          orderId: orderNumber
        });

        window.open(url, "_blank");
        clearCart();
        toast.success("Order placed successfully!");
        navigate("/profile");
        setLoading(false);
      }

    } catch (error: any) {
      console.error("Checkout Error:", error);
      toast.error("Failed to place order: " + (error.message || "Unknown error"));
      setLoading(false);
    }
  };

  const handlePaymentConfirmed = async () => {
    setLoading(true);
    try {
      // Update order status to pending
      const { error: updateError } = await supabase
        .from('orders')
        .update({ status: 'pending' })
        .eq('id', currentOrderData.orderId);

      if (updateError) throw updateError;

      // Open WhatsApp
      const url = generateWhatsAppOrderUrl({
        products: items.map((item) => ({
          name: item.product.name,
          price: item.product.price * item.quantity,
          quantity: item.quantity,
        })),
        total: grandTotal,
        shippingFee: shippingFee,
        customerName: form.name,
        customerPhone: form.phone,
        customerAddress: `${form.address}, ${form.pincode}`,
        orderId: currentOrderData.orderNumber
      });

      window.open(url, "_blank");
      clearCart();
      setShowPaymentDialog(false);
      toast.success("Order placed successfully!");
      navigate("/profile");
    } catch (error: any) {
      console.error("Payment confirmation error:", error);
      toast.error("Failed to confirm payment: " + (error.message || "Unknown error"));
    } finally {
      setLoading(false);
    }
  };

  const handlePaymentCancelled = async () => {
    setLoading(true);
    try {
      // Update order status to cancelled
      const { error: updateError } = await supabase
        .from('orders')
        .update({ status: 'cancelled' })
        .eq('id', currentOrderData.orderId);

      if (updateError) throw updateError;

      setShowPaymentDialog(false);
      toast.error("Payment cancelled. Please try again.");
    } catch (error: any) {
      console.error("Payment cancellation error:", error);
      toast.error("Failed to cancel order: " + (error.message || "Unknown error"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8 lg:py-12 max-w-lg">
        <Link to="/cart" className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-primary transition-colors mb-6">
          <ArrowLeft className="w-4 h-4" /> Back to Cart
        </Link>

        <h1 className="font-heading text-2xl lg:text-3xl font-bold text-foreground mb-8">Checkout</h1>

        {/* Order summary */}
        <div className="bg-card rounded-2xl p-5 shadow-soft border border-border mb-6">
          <h2 className="font-heading text-sm font-semibold text-foreground mb-3">Order Summary</h2>
          {items.map((item) => (
            <div key={item.product.id} className="flex justify-between text-sm py-1.5 border-b border-border last:border-0">
              <span className="text-muted-foreground">{item.product.name} × {item.quantity}</span>
              <span className="text-foreground font-medium">₹{(item.product.price * item.quantity).toLocaleString("en-IN")}</span>
            </div>
          ))}
          <div className="flex justify-between py-1.5 border-b border-border last:border-0 text-sm">
            <span className="text-muted-foreground">Shipping Fee</span>
            <span className="text-foreground font-medium">
              {shippingFee === 0 ? (
                <span className="text-green-600 font-bold">FREE</span>
