        .channel(`product-detail-${id}`)
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'products',
            filter: `id=eq.${id}`
          },
          (payload) => {
            console.log("Realtime update received:", payload);
            setProduct((prev) => {
              if (!prev) return null;
              // Merge the new data (payload.new) with existing product data
              // payload.new contains the raw DB row, so we need to ensure types match if necessary
              // but mostly it maps 1:1 for simple fields like stock_quantity
              return { ...prev, ...payload.new as any };
            });

            // Also update main image if it changed and we are showing it
            if (payload.new.images && payload.new.images.length > 0) {
              // Optional: Logic to update image if needed, but usually stock is the main concern
            }
          }
        )
        .subscribe();

      return () => {
        supabase.removeChannel(channel).catch(() => { });
      };
    }
  }, [id]);

  const fetchProduct = async (productId: string) => {
    setLoading(true);
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .eq('id', productId)
      .single();

    if (error) {
      console.error('Error fetching product:', error);
      toast.error("Failed to load product details");
    } else {
      setProduct(data);
      // Set initial main image
      if (data.images && data.images.length > 0) {
        setMainImage(data.images[0]);
      } else {
        setMainImage(data.image_url || '/placeholder.svg');
      }
    }
    setLoading(false);
  };

  const isOutOfStock = (product: Product) => {
    // Check numeric quantity first if available
    if (product.stock_quantity !== undefined) {
      return product.stock_quantity <= 0;
    }
    // Fallback to string status
    return product.stock === "Out of Stock";
  };

  const handleAddToCart = () => {
    if (!user) {
      toast.error("Please login to add items to cart");
      navigate("/login", { state: { from: location } });
      return;
    }

    if (product) {
      // Cast to any if necessary to bypass strict type check until global type is updated
      addToCart({
        ...product,
        stock_quantity: product.stock_quantity
      } as any);
      toast.success("Added to cart");
    }
  };

  const handleBuyNow = () => {
    if (!user) {
      toast.error("Please login to proceed to checkout");
      navigate("/login", { state: { from: location } });
      return;
    }

    if (product) {
      addToCart({
        ...product,
        stock_quantity: product.stock_quantity
      } as any);
      navigate("/checkout");
    }
  };

  const getStockLabel = (product: Product) => {
    if (product.stock_quantity !== undefined) {
      if (product.stock_quantity <= 0) return { text: "Out of Stock", color: "text-red-600 bg-red-50" };
      if (product.stock_quantity < 5) return { text: `Low Stock: Only ${product.stock_quantity} left!`, color: "text-orange-600 bg-orange-50" };
      return { text: "In Stock", color: "text-green-600 bg-green-50" };
    }
    // Fallback
    if (product.stock === "Out of Stock") return { text: "Out of Stock", color: "text-red-600 bg-red-50" };
    if (product.stock === "Low Stock") return { text: "Low Stock", color: "text-orange-600 bg-orange-50" };
    return { text: "In Stock", color: "text-green-600 bg-green-50" };
  };

  if (loading) {
    return (
      <div className="flex h-[80vh] items-center justify-center">
        <Loader2 className="h-10 w-10 animate-spin text-primary" />
      </div>
    );
  }

  if (!product) {
    return (
      <div className="container mx-auto px-4 py-16 text-center">
        <h2 className="text-2xl font-bold mb-4">Product not found</h2>
        <Button asChild>
          <Link to="/shop">Back to Shop</Link>
        </Button>
      </div>
    );
  }

  // Handle both camelCase (from mock) and snake_case (from DB) for price
  const originalPrice = product.original_price;

  const discount = originalPrice
    ? Math.round(((originalPrice - product.price) / originalPrice) * 100)
    : 0;

  const shareText = encodeURIComponent(`Check out ${product.name} — ₹${product.price.toLocaleString("en-IN")} at KVP Fancy Jewellery!`);
  const shareUrl = `https://wa.me/?text=${shareText}`;

  // Use images array if available, otherwise fallback to single image
  const galleryImages = product.images && product.images.length > 0
    ? product.images
    : [product.image_url || '/placeholder.svg'];

  const stockInfo = getStockLabel(product);
  const cartItem = items.find(i => i.product.id === product?.id);
  const isAtMaxStock = cartItem && product && cartItem.quantity >= (product.stock_quantity ?? 0);
  const disableCart = isOutOfStock(product) || isAtMaxStock;

  // Structured Data (JSON-LD) for SEO
  const structuredData = {
    "@context": "https://schema.org/",
    "@type": "Product",
    "name": product.name,
    "image": product.images && product.images.length > 0 ? product.images : [product.image_url],
    "description": product.description || `Buy ${product.name} at KVP Fancy Jewellery. Premium quality gold jewellery.`,
    "sku": product.id,
    "brand": {
      "@type": "Brand",
      "name": "KVP Fancy Jewellery"
    },
    "offers": {
      "@type": "Offer",
      "url": window.location.href,
      "priceCurrency": "INR",
      "price": product.price,
      "availability": disableCart ? "https://schema.org/OutOfStock" : "https://schema.org/InStock",
      "priceValidUntil": "2026-12-31"
    },
    "aggregateRating": {
      "@type": "AggregateRating",
      "ratingValue": product.avg_rating || 5,
      "reviewCount": product.review_count || 1
    }
  };

  return (
    <div className="min-h-screen bg-background pt-24 pb-16">
      <MetaTags
        title={`${product.name} — Luxury Gold Jewellery | KVP`}
        description={product.description?.substring(0, 160) || `Buy handcrafted ${product.name} at KVP Fancy Jewellery. Premium quality gold jewellery for every occasion.`}
        image={product.image_url}
      />

      <script type="application/ld+json">
        {JSON.stringify(structuredData)}
      </script>

      <div className="container mx-auto px-4">
        <Button
          variant="ghost"
          className="mb-8 pl-0 hover:pl-2 transition-all"
          asChild
        >
          <Link to="/shop">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Shop
          </Link>
        </Button>

        <div className="grid lg:grid-cols-2 gap-12 lg:gap-16">
          {/* Image Gallery */}
          <div className="space-y-4">
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className="rounded-2xl overflow-hidden shadow-elevated aspect-square bg-card"
            >
              <CloudinaryImage
                src={mainImage}
                alt={product.name}
                className="w-full h-full object-cover"
                priority={true}
              />
            </motion.div>

            {/* Thumbnails */}
            {galleryImages.length > 1 && (
              <div className="flex gap-2 overflow-x-auto pb-2">
                {galleryImages.map((img, index) => (
                  <button
                    key={index}
                    onClick={() => setMainImage(img)}
                    className={`relative w-20 h-20 rounded-lg overflow-hidden flex-shrink-0 border-2 transition-all ${mainImage === img ? "border-primary" : "border-transparent hover:border-primary/50"
                      }`}
                  >
                    <CloudinaryImage
                      src={img}
                      alt={`${product.name} ${index + 1}`}
                      className="w-full h-full object-cover"
                      width={80}
                      height={80}
                    />
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Product Info */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            className="space-y-6 lg:space-y-8"
          >
            <div className="space-y-3 sm:space-y-4">
              <span className="text-[10px] sm:text-xs font-bold text-primary tracking-[0.2em] uppercase">
                {product.category}
              </span>
              <h1 className="text-2xl sm:text-3xl lg:text-5xl font-heading font-bold text-foreground leading-tight">
                {product.name}
              </h1>
              <div className="flex flex-wrap items-center gap-3 sm:gap-6">
                <div className="flex items-baseline gap-2">
                  <span className="text-2xl sm:text-3xl font-black text-primary">₹{product.price.toLocaleString("en-IN")}</span>
                  {originalPrice && (
                    <span className="text-sm sm:text-base text-muted-foreground line-through decoration-primary/30">
                      ₹{originalPrice.toLocaleString("en-IN")}
                    </span>
                  )}
                </div>
                {originalPrice && (
                  <span className="bg-primary/10 text-primary text-[10px] sm:text-xs px-3 py-1.5 rounded-full font-bold uppercase tracking-wider">{discount}% OFF</span>
                )}
                <div className="flex items-center gap-1.5 bg-amber-50 px-3 py-1.5 rounded-xl border border-amber-100 flex-shrink-0">
                  <Star className="w-4 h-4 fill-amber-400 text-amber-400" />
                  <span className="text-sm font-black text-amber-700">
                    {product.avg_rating ? Number(product.avg_rating).toFixed(1) : "5.0"}
                  </span>
                  <span className="text-xs text-amber-500/70 font-bold">({product.review_count || 0})</span>
                </div>
              </div>
              <div className="inline-block">
                <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest ${stockInfo.color}`}>
                  {stockInfo.text}
                </span>
              </div>
            </div>

            <p className="text-muted-foreground text-sm sm:text-base leading-relaxed max-w-2xl border-l-2 border-primary/20 pl-4 py-1">
              {product.description || "Indulge in the luxury of handcrafted gold jewellery, designed to make every moment special."}
            </p>

            <div className="flex flex-col sm:flex-row gap-4 pt-4">
              <Button
                size="lg"
                className="flex-1 text-sm font-bold tracking-widest h-14 gradient-gold text-primary-foreground border-none shadow-gold hover:shadow-elevated transition-all rounded-full"
                onClick={handleBuyNow}
                disabled={disableCart}
              >
                BUY NOW
              </Button>
              <Button
                variant="secondary"
                size="lg"
                className="flex-1 text-sm font-bold tracking-widest h-14 bg-primary/5 text-primary hover:bg-primary/10 border-none transition-all rounded-full"
                onClick={handleAddToCart}
                disabled={disableCart}
              >
                <ShoppingBag className="mr-2 h-5 w-5" />
                {isAtMaxStock ? "MAX QTY" : (disableCart ? "SOLD OUT" : "ADD TO CART")}
              </Button>
            </div>
            <div className="flex flex-col sm:flex-row gap-4">
              <Button
                variant="outline"
                size="lg"
                className="flex-1 text-base h-12"
                onClick={() => window.open(generateProductWhatsAppUrl(product.name, product.price), '_blank')}
              >
                <MessageCircle className="mr-2 h-5 w-5" />
                Enquire on WhatsApp
              </Button>
              <Button
                size="icon"
                variant="outline"
                className="h-12 w-12"
                onClick={() => window.open(shareUrl, '_blank')}
              >
                <Share2 className="h-5 w-5" />
              </Button>
            </div>

            <div className="grid grid-cols-2 gap-4 py-6">
              <div className="flex items-center gap-3 text-sm text-muted-foreground">
                <Check className="h-5 w-5 text-primary" />
                <span>Certified Quality</span>
              </div>
              <div className="flex items-center gap-3 text-sm text-muted-foreground">
                <Check className="h-5 w-5 text-primary" />
                <span>Secure Shipping</span>
              </div>
              <div className="flex items-center gap-3 text-sm text-muted-foreground">
                <Check className="h-5 w-5 text-primary" />
                <span>Lifetime Support</span>
              </div>
              <div className="flex items-center gap-3 text-sm text-muted-foreground">
                <Check className="h-5 w-5 text-primary" />
                <span>Easy Returns</span>
              </div>
            </div>

            {/* Product Reviews Section */}
            <div className="pt-8 border-t">
              <h3 className="text-xl font-bold mb-6">Write a Review</h3>
              <ReviewForm productId={id || ""} productName={product.name} />
            </div>

            {/* Related Products Section */}
            <RelatedProducts currentProductId={product.id} category={product.category} />
          </motion.div>
        </div>
      </div>
    </div>
  );
};

// Simple Review Form Component
const ReviewForm = ({ productId, productName }: { productId: string, productName: string }) => {
  const [rating, setRating] = useState(5);
  const [name, setName] = useState("");
  const [content, setContent] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !content) {
      toast.error("Please fill in all fields");
      return;
    }

    setSubmitting(true);
    try {
      const { error } = await supabase
        .from('testimonials')
        .insert([{
          name,
          content,
          rating,
          product_id: productId,
          role: "Verified Buyer",
          is_active: false // Requires admin approval
        }]);

      if (error) throw error;

      toast.success("Review submitted! It will appear after approval.");
      setName("");
      setContent("");
      setRating(5);
    } catch (error) {
      console.error("Error submitting review:", error);
      toast.error("Failed to submit review");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4 bg-secondary/30 p-6 rounded-xl">
      <div className="space-y-2">
        <label className="text-sm font-medium">Rating</label>
        <div className="flex gap-1">
          {[1, 2, 3, 4, 5].map((star) => (
            <button
              key={star}
              type="button"
              onClick={() => setRating(star)}
              className={`p-1 transition-colors ${rating >= star ? "text-amber-400" : "text-gray-300"}`}
            >
              <Check className={`w-6 h-6 fill-current ${rating >= star ? "fill-amber-400" : "fill-none"}`} style={{ visibility: 'hidden', width: 0, height: 0 }} />
              {/* Using Star icon actually */}
              <svg
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 24 24"
                fill={rating >= star ? "currentColor" : "none"}
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                className="w-6 h-6"
              >
                <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
              </svg>
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-2">
        <label htmlFor="reviewer-name" className="text-sm font-medium">Your Name</label>
        <input
          id="reviewer-name"
          className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Enter your name"
          required
        />
      </div>

      <div className="space-y-2">
        <label htmlFor="review-content" className="text-sm font-medium">Your Review</label>
        <textarea
          id="review-content"
          className="flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder={`How do you like the ${productName}?`}
          required
          rows={3}
        />
      </div>

      <Button type="submit" disabled={submitting} className="w-full">
        {submitting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
        Submit Review
      </Button>
    </form>
  );
};

export default ProductDetail;

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { supabase } from "@/lib/supabaseClient";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import { Loader2, Package, User, Settings, LogOut } from "lucide-react";
import { toast } from "sonner";
import { OrderCard, Order } from "@/components/profile/OrderCard";
import { OrderTracking } from "@/components/profile/OrderTracking";

const Profile = () => {
    const { user, profile, signOut, loading: authLoading, displayIdentifier } = useAuth();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [orders, setOrders] = useState<Order[]>([]);
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [trackingOpen, setTrackingOpen] = useState(false);

    useEffect(() => {
        if (!authLoading && !user) {
            const timer = setTimeout(() => {
                navigate("/login");
            }, 500);
            return () => clearTimeout(timer);
        }

        // EAGER FETCH: Start fetching as soon as we have a user ID, 
        // don't wait for authLoading (role check) to finish.
        if (user) {
            fetchOrders();

            // REALTIME: Listen for new orders or status updates
            const channel = supabase
                .channel(`user-orders-${user.id}`)
                .on(
                    'postgres_changes',
                    {
                        event: '*',
                        schema: 'public',
                        table: 'orders',
                        filter: `user_id=eq.${user.id}`
                    },
                    (payload) => {
                        console.log('📦 Realtime order update:', payload);
                        fetchOrders(); // Refetch to get items joined
                    }
                )
                .subscribe();

            return () => {
                supabase.removeChannel(channel);
            };
        }
    }, [user?.id, authLoading]);

    const fetchOrders = async () => {
        try {
            setLoading(true);
            if (!user) {
                console.log('⚠️ fetchOrders called but no user available');
                return;
            }

            console.log('📦 Fetching orders for user:', user.id);
            const { data, error } = await supabase
                .from('orders')
                .select(`
          *,
          order_items(*)
        `)
                .eq('user_id', user.id)
                .order('created_at', { ascending: false });

            if (error) {
                console.error('❌ Error fetching orders:', error);
                throw error;
            }

            console.log('✅ Orders fetched successfully:', data?.length || 0, 'orders');
            console.log('📋 Order data:', data);

            // Transform data to match Order interface if needed, or cast if it matches
            setOrders(data as Order[]);
        } catch (error: any) {
            console.error('❌ Error in fetchOrders:', error);
            // Don't show error toast if it's just empty orders
        } finally {
            setLoading(false);
        }
    };

    const handleTrackOrder = (order: Order) => {
        setSelectedOrder(order);
        setTrackingOpen(true);
    };

    const handleLogout = async () => {
        await signOut();
        toast.success("Logged out successfully");
        navigate("/");
    };

    if (authLoading) {
        return (
            <div className="flex h-[60vh] items-center justify-center">
                <Loader2 className="h-10 w-10 animate-spin text-primary" />
            </div>
        );
    }

    if (!user) return null;

    return (
        <div className="container mx-auto px-4 py-8 min-h-[60vh]">
            <div className="flex flex-col md:flex-row gap-6">
                {/* Sidebar / Mobile Tabs */}
                <div className="w-full md:w-64 flex-shrink-0">
                    <Card className="border-border/60">
                        <CardContent className="p-6 text-center">
                            <div className="w-20 h-20 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4">
                                <span className="text-2xl font-bold text-primary">
                                    {(displayIdentifier || 'U').charAt(0).toUpperCase()}
                                </span>
                            </div>
                            <h2 className="font-bold text-lg truncate" title={displayIdentifier || ''}>{displayIdentifier}</h2>
                            <p className="text-sm text-muted-foreground">Member</p>
                        </CardContent>
                    </Card>
                </div>

                {/* Main Content */}
                <div className="flex-1">
                    <Tabs defaultValue="orders" className="w-full">
                        <TabsList className="grid w-full grid-cols-3 mb-8">
                            <TabsTrigger value="orders">
                                <Package className="w-4 h-4 mr-2" />
                                Requests
                            </TabsTrigger>
                            <TabsTrigger value="account">
                                <User className="w-4 h-4 mr-2" />
                                Account
                            </TabsTrigger>
                            <TabsTrigger value="settings">
                                <Settings className="w-4 h-4 mr-2" />
                                Settings
                            </TabsTrigger>
                        </TabsList>

                        <TabsContent value="orders" className="space-y-6">
                            <div className="flex items-center justify-between">
                                <h2 className="text-2xl font-bold">My Orders</h2>
                                <Button variant="outline" size="sm" onClick={fetchOrders} disabled={loading}>
                                    {loading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                                    Refresh
                                </Button>
                            </div>

                            {loading ? (
                                <div className="flex justify-center py-12">
                                    <Loader2 className="w-8 h-8 animate-spin text-primary" />
                                </div>
                            ) : orders.length > 0 ? (
                                <div className="grid gap-6">
                                    {orders.map((order) => (
                                        <OrderCard
                                            key={order.id}
                                            order={order}
                                            onTrackOrder={handleTrackOrder}
                                        />
                                    ))}
                                </div>
                            ) : (
                                <Card>
                                    <CardContent className="flex flex-col items-center justify-center py-12 text-center">
                                        <Package className="w-12 h-12 text-muted-foreground mb-4 opacity-50" />
                                        <h3 className="text-lg font-medium mb-2">No orders yet</h3>
                                        <p className="text-muted-foreground mb-6">You haven't placed any orders yet.</p>
                                        <Button onClick={() => navigate("/shop")}>Start Shopping</Button>
                                    </CardContent>
                                </Card>
                            )}
                        </TabsContent>

                        <TabsContent value="account">
                            <Card>
                                <CardHeader>
                                    <CardTitle>Account Details</CardTitle>
                                    <CardDescription>Manage your account information.</CardDescription>
                                </CardHeader>
                                <CardContent className="space-y-4">
                                    <div className="space-y-2">
                                        <Label htmlFor="identifier">Account ID</Label>
                                        <Input id="identifier" value={displayIdentifier || ''} disabled />
                                    </div>
                                    <div className="space-y-2">
                                        <Label htmlFor="fullname">Full Name</Label>
                                        <Input id="fullname" value={profile?.full_name || ''} disabled />
                                    </div>
                                    {profile?.phone_number && (
                                        <div className="space-y-2">
                                            <Label htmlFor="phone">Phone Number</Label>
                                            <Input id="phone" value={profile.phone_number} disabled />
                                        </div>
                                    )}
                                </CardContent>
                            </Card>
                        </TabsContent>

                        <TabsContent value="settings">
                            <Card>
                                <CardHeader>
                                    <CardTitle>Settings</CardTitle>
                                    <CardDescription>Manage your app preferences.</CardDescription>
                                </CardHeader>
                                <CardContent className="space-y-4">
                                    <div className="pt-4">
                                        <Button variant="destructive" className="w-full sm:w-auto" onClick={handleLogout}>
                                            <LogOut className="w-4 h-4 mr-2" />
                                            Log Out
                                        </Button>
                                    </div>
                                </CardContent>
                            </Card>
                        </TabsContent>
                    </Tabs>
                </div>
            </div>

            <OrderTracking
                order={selectedOrder}
                open={trackingOpen}
                onOpenChange={setTrackingOpen}
            />
        </div>
    );
};

export default Profile;

